77	    private void seedDashboardSettings(Map<String, Object> fixture) {
78	        Object asOf = fixture.get("asOf");
79	        if (asOf != null) {
80	            jdbc.update("INSERT INTO dashboard_settings (id, as_of) VALUES (1, ?)",
81	                    Date.valueOf(asOf.toString()));
82	        }
83	    }
