85	    private void seedClients(Map<String, Object> fixture) {
86	        for (Map<String, Object> c : rows(fixture, "clients")) {
87	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
88	                    id(c, "id"), c.get("name"), c.get("email"));
89	        }
90	    }
