// Data access + validation for the clients feature, kept in one place so the page and its forms
// share a single definition of "what a client is" and "how we talk to the server" (CLAUDE.md —
// keep each feature's code together; features own their state).
export type Client = { id: number; name: string; email: string };

// Every client needs a proper email address. Kept in sync with the server-side check in
// ClientsPostLogic and the DB CHECK constraint (V2__clients_email_check.sql).
const EMAIL_PATTERN = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

export const INVALID_EMAIL = 'Enter a valid email address.';
export const DUPLICATE_EMAIL = 'A client with this email already exists.';

// Validate an email before it reaches the server. `takenEmails` are the emails this one must not
// collide with (the server and the clients_email_unique constraint are the authoritative guards).
// Returns the error to show, or '' when the email is acceptable.
export function validateEmail(email: string, takenEmails: string[]): string {
  const trimmed = email.trim();
  if (!EMAIL_PATTERN.test(trimmed)) {
    return INVALID_EMAIL;
  }
  if (takenEmails.includes(trimmed)) {
    return DUPLICATE_EMAIL;
  }
  return '';
}

// Load the full client list. Returns null when the request fails so callers can keep what they
// already have rather than blanking the list.
export async function fetchClients(): Promise<Client[] | null> {
  const res = await fetch('/api/clients');
  return res.ok ? res.json() : null;
}

export async function createClient(input: { name: string; email: string }): Promise<Response> {
  return fetch('/api/clients', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
}

export async function updateClient(input: {
  id: number;
  name: string;
  email: string;
}): Promise<Response> {
  return fetch('/api/clients/update', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  });
}

export async function archiveClient(id: number): Promise<Response> {
  return fetch('/api/clients/archive', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ id }),
  });
}

import React, { useEffect, useState } from 'react';
import { Client, archiveClient, fetchClients } from './clientsApi';
import { ClientForm } from './ClientForm';
import { ClientEditForm } from './ClientEditForm';
import { ClientsTable } from './ClientsTable';
import { ClientDetails } from './ClientDetails';

// Clients feature: owns its own state (CLAUDE.md — features own their state, no global store).
// The page orchestrates; the form, table and detail panels each keep their own concerns.
export function ClientsPage() {
  const [clients, setClients] = useState<Client[]>([]);
  const [search, setSearch] = useState('');
  const [openClientId, setOpenClientId] = useState<number | null>(null);
  const [editingClientId, setEditingClientId] = useState<number | null>(null);

  async function load() {
    const loaded = await fetchClients();
    if (loaded) {
      setClients(loaded);
    }
  }

  useEffect(() => {
    void load();
  }, []);

  // The list can get long; filter by name, case-insensitively. Empty box shows every client.
  const query = search.trim().toLowerCase();
  const visibleClients = query
    ? clients.filter((c) => c.name.toLowerCase().includes(query))
    : clients;

  function onCreated(created: Client) {
    setClients((prev) => [...prev, created]);
  }

  // A saved edit replaces the row in place; the edit form then closes.
  function onSaved(saved: Client) {
    setClients((prev) => prev.map((c) => (c.id === saved.id ? saved : c)));
    setEditingClientId(null);
  }

  const editingClient = clients.find((c) => c.id === editingClientId) ?? null;

  // Tuck a client away: it drops off the list and the search, but the row is kept server-side.
  async function onArchive(id: number) {
    const res = await archiveClient(id);
    if (res.ok) {
      setClients((prev) => prev.filter((c) => c.id !== id));
      setOpenClientId((prev) => (prev === id ? null : prev));
    }
  }

  return (
    <section data-testid="clients-page">
      <h1>Clients</h1>
      <ClientForm takenEmails={clients.map((c) => c.email)} onCreated={onCreated} />

      <input
        data-testid="client-search"
        placeholder="Search by name"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      {clients.length === 0 ? (
        <p data-testid="clients-empty">No clients yet.</p>
      ) : (
        <ClientsTable
          clients={visibleClients}
          onOpen={setOpenClientId}
          onEdit={setEditingClientId}
          onArchive={onArchive}
        />
      )}

      {editingClient ? (
        <ClientEditForm
          key={editingClient.id}
          client={editingClient}
          takenEmails={clients.filter((c) => c.id !== editingClient.id).map((c) => c.email)}
          onSaved={onSaved}
          onCancel={() => setEditingClientId(null)}
        />
      ) : null}

      {openClientId !== null ? <ClientDetails clientId={openClientId} /> : null}
    </section>
  );
}

